// The published worker caches only the versioned static app shell generated by Blazor.
self.importScripts('./service-worker-assets.js');

self.addEventListener('install', event => event.waitUntil(onInstall()));
self.addEventListener('activate', event => event.waitUntil(onActivate()));
self.addEventListener('fetch', event => event.respondWith(onFetch(event)));
self.addEventListener('message', event => {
    if (event.data?.type === 'SKIP_WAITING') {
        self.skipWaiting();
    }
});

const cacheNamePrefix = 'detara-app-shell-';
const cacheName = `${cacheNamePrefix}${self.assetsManifest.version}`;
const offlineAssetsInclude = [
    /\.html$/,
    /\.css$/,
    /\.js$/,
    /\.json$/,
    /\.wasm$/,
    /\.woff2?$/,
    /\.png$/,
    /\.jpe?g$/,
    /\.gif$/,
    /\.ico$/,
    /\.webmanifest$/,
    /\.blat$/,
    /\.dat$/
];
const offlineAssetsExclude = [/^service-worker\.js$/];
const baseUrl = new URL(self.registration.scope);
const manifestUrlList = self.assetsManifest.assets.map(asset => new URL(asset.url, baseUrl).href);
const indexUrl = new URL('index.html', baseUrl).href;

async function onInstall() {
    const assetsRequests = self.assetsManifest.assets
        .filter(asset => offlineAssetsInclude.some(pattern => pattern.test(asset.url)))
        .filter(asset => !offlineAssetsExclude.some(pattern => pattern.test(asset.url)))
        .map(asset => new Request(new URL(asset.url, baseUrl), {
            integrity: asset.hash,
            cache: 'no-cache'
        }));

    const cache = await caches.open(cacheName);
    await cache.addAll(assetsRequests);
}

async function onActivate() {
    const cacheKeys = await caches.keys();
    await Promise.all(cacheKeys
        .filter(key => key.startsWith(cacheNamePrefix) && key !== cacheName)
        .map(key => caches.delete(key)));
    await self.clients.claim();
}

async function onFetch(event) {
    const request = event.request;
    const requestUrl = new URL(request.url);

    // API, authentication and any cross-origin request are always network-only.
    if (request.method !== 'GET' ||
        requestUrl.origin !== self.location.origin ||
        requestUrl.pathname.startsWith(new URL('api/', baseUrl).pathname) ||
        request.headers.has('Authorization')) {
        return fetch(request);
    }

    const shouldServeIndexHtml = request.mode === 'navigate' &&
        !manifestUrlList.includes(request.url);
    const cacheRequest = shouldServeIndexHtml ? indexUrl : request;
    const cache = await caches.open(cacheName);
    const cachedResponse = await cache.match(cacheRequest);

    return cachedResponse || fetch(request);
}
